    if (state.effects[i].life <= 0) state.effectPool.push(state.effects.splice(i, 1)[0]);
  }
  // 先判斷碰撞，再減少無敵時間，避免最後一幀又被撞一次。
  if (!state.player.damageDisabled && state.player.invincible <= 0) {
    const touchingEnemy = state.enemies.find((enemy) => enemy.alive && (enemy.miniboss || !GAME_DATA.bodyContact.pushOnly) && Math.hypot(deltaX(enemy.x, state.player.x), deltaY(enemy.y, state.player.y)) < enemy.r + state.player.r - 2);
    const touchingBoss = state.boss && targetVisible(state.boss) && state.bossIntro <= 0 && state.bossPhasePause <= 0 && !state.bossMoves.some(move => bossKind(move) === "dash") && Math.hypot(deltaX(state.boss.x, state.player.x), deltaY(state.boss.y, state.player.y)) < state.boss.r + state.player.r - 2;
    if (touchingEnemy || touchingBoss) {
      state.player.health = Math.max(0, state.player.health - absorbSchoolHit(touchingEnemy ? bodyContactDamage(touchingEnemy) : UPGRADE_TUNING.enemyDamage));
      counterDischarge(); if (state.mode !== "playing") return;
      state.player.invincible = INVINCIBLE_SECONDS;
      state.player.hitFlash = 0.16;
      if (gameSettings.vibration && navigator.vibrate) navigator.vibrate(35);
      playSound("hurt");
      updateHud();
    }
  }
  const bodyPass = dashTime>0 || state.dashBodyPass>0;
  separateEnemyBodies(dt,{x:oldX,y:oldY},bodyPass);
  state.dashBodyPass = countdown(state.dashBodyPass,dt);
  // 保留舊作品「只推開」行為；新分離關閉時才使用，不阻擋衝刺。
  if(!GAME_DATA.bodySeparation.enabled && !bodyPass) pushEnemyBodies();
  state.player.invincible = Math.max(0, state.player.invincible - dt);
  state.player.hitFlash = Math.max(0, state.player.hitFlash - dt);
  if (state.player.health <= 0) { finishRun(false); return; }
  statusEl.textContent = `${Math.floor(state.elapsed)} 秒`;
}

applyUpgrade:
function applyUpgrade(index, choices = state.pendingChoices) {
  if (choices !== state.pendingChoices) return;
  const card = state.pendingChoices[index]; if (!card || state.mode !== "levelup" || (!state.pickingWeapon && card.id !== "heal" && !canOffer(card))) return;
  if (globalThis.SurvivorPreview) SurvivorPreview.stop();
  if (state.pickingWeapon) {
    state.weaponId = card.id; state.pickingWeapon = false; state.pendingChoices = [];
    overlay.classList.add('hidden'); state.mode = 'playing'; spawnEnemy();
    playSound('select'); updateActionControls(); updateHud(); state.lastTime = performance.now(); scheduleFrame(); return;
  }
  const before = { ...state.upgrades };
  if (card.id === "heal") state.player.health = Math.min(maxPlayerHealth(), state.player.health + Math.ceil(PLAYER_HEALTH / BUILD_TUNING.shieldHealthDivisor));
  else { state.upgrades[card.id] = upgradeLevel(card.id) + 1; if (upgradeLevel(card.id) === 1 && card.effects.some(e => e.feature === "water-ultimate")) state.ultimateTimer = BUILD_TUNING.ultimateSeconds; if (card.effects.some(e => e.feature === "bubble-shield")) { state.player.health = Math.min(maxPlayerHealth(), state.player.health + Math.ceil(PLAYER_HEALTH / BUILD_TUNING.shieldHealthDivisor)); } }
  neutralEvent('acquire', state.player.x, state.player.y, card.id);
  state.player.health = Math.min(state.player.health, maxPlayerHealth());
  if (state.schoolRun && !state.schoolRun.starter && card.school) state.schoolRun.starter = card.school;
  if (card.id === 'water-ultimate') { state.ultimateTimers = state.ultimateTimers || {}; state.ultimateTimers.water = BUILD_TUNING.ultimateSeconds; }
  handleSchoolEvents(SurvivorSchools.growth(UPGRADES, before, state.upgrades, GAME_DATA.schoolRules));
  skillVisual("card", state.player.x, state.player.y - 38, { text: card.icon || "health", color: card.school ? BUILD_TUNING[card.school].color : "#237bc2", life: .8 });
  playSound("select");
  if (state.rewardPicking) {
    state.rewardPicked.push(card.id); state.rewardChoices--;
    if (state.rewardChoices > 0) { chooseUpgradeCards(); return; }
    state.rewardPicking = false; state.rewardPicked = [];
  }
  state.pendingChoices = []; overlay.classList.add("hidden"); state.mode = "playing"; SurvivorIcons.set(pauseButton, "settings"); updateActionControls(); updateHud(); state.lastTime = performance.now(); scheduleFrame();
}

drawNeutralItems:
function drawNeutralItems() {
  if (!state.neutral) return;
  const p=state.player;
  if (effectLevel('item-bird')) {const pos=neutralBirdPosition();SurvivorIcons.draw(ctx,'item-bird',pos.x-12,pos.y-12,24);}
  for(const bomb of state.neutral.bombs) SurvivorIcons.draw(ctx,'item-candy',bomb.x-12,bomb.y-12,24+Math.sin(bomb.timer*20)*2);
  if (effectLevel('item-magnet')) {
    const radius=GEM_PULL_RADIUS*GAME_DATA.neutralRules.magnetMultiplier*cardBlock('wind-light','onPickup').actions[0].multiplier*(1+effectLevel('gem-magnet')*UPGRADE_TUNING.magnetPerLevel);
    ctx.save();ctx.globalAlpha=.25;ctx.strokeStyle='#e5c77d';ctx.lineWidth=1;ctx.beginPath();ctx.arc(p.x,p.y,radius,0,Math.PI*2);ctx.stroke();ctx.restore();
  }
  ['crown','bank','clover','cookie'].filter(id=>effectLevel('item-'+id)).forEach((id,i)=>{
    SurvivorIcons.draw(ctx,'item-'+id,p.x-28+i*18,p.y-p.r-30,16);
    if(id==='bank'||id==='cookie') {ctx.fillStyle='#fff1b9';ctx.font='10px sans-serif';ctx.fillText(String(id==='bank'?Math.round(Math.min(GAME_DATA.neutralRules.bankCap,Math.floor(state.neutral.gems/GAME_DATA.neutralRules.bankEvery)*GAME_DATA.neutralRules.bankStep)*100)+'%':state.neutral.kills%GAME_DATA.neutralRules.cookieKills),p.x-28+i*18,p.y-p.r-32);}
  });
}
